	@ParameterizedTest
	@MethodSource("allRawComponentKinds")
	void allRawKindsRoundTripAcrossTheNativePackedAdapterAndKeepTheirOwnIdentity(String component,
			LmdbValueIdFilter.Kind kind) {
		StatementPattern plain = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"), Var.of("g"));
		StatementPattern source = plain.clone();
		String specification = component + ':' + kind.name();
		source.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, specification);
		long word = LmdbValueIdFilter.fromStatementPattern(source).semanticKindWord();
		assertTrue(word != 0L, specification);
		var call = PackedCostTestSupport.unaryOperator(PlanningGraphDomain.defaultGraph(),
				new Filter(source, truth()), LmdbStatementPatternSemanticsCodec.INSTANCE);
		StatementPattern copied = (StatementPattern) call.query().materializeRelation(call.inputRelationId());
		assertEquals(specification, copied.getStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER));
		assertEquals(word, LmdbValueIdFilter.fromStatementPattern(copied).semanticKindWord());
		assertNotEquals(leafKey(plain), leafKey(source));
		assertEquals(leafKey(source), leafKey(copied));
	}

	private static Stream<Arguments> allRawComponentKinds() {
		return Stream.of("subject", "predicate", "object", "context")
				.flatMap(component -> Arrays.stream(LmdbValueIdFilter.Kind.values())
						.filter(kind -> kind != LmdbValueIdFilter.Kind.NAMED_GRAPH)
						.map(kind -> Arguments.of(component, kind)));
	}

