	@Test
	void numericAndDatatypeRawKindsKeepGenericLiteralAdmissionSeparateFromInlineTypes() {
		long genericLiteral = ValueIds.createId(ValueIds.T_LITERAL, 7L);
		long integer = ValueIds.createId(ValueIds.T_INTEGER, 7L);
		long decimal = ValueIds.createId(ValueIds.T_DECIMAL, 7L);
		long string = ValueIds.createId(ValueIds.T_SHORTSTRING, 7L);
		long iri = ValueIds.createId(ValueIds.T_URI, 7L);
		assertTrue(LmdbValueIdFilter.Kind.NUMERIC.accept(genericLiteral));
		assertTrue(LmdbValueIdFilter.Kind.NUMERIC.accept(integer));
		assertTrue(LmdbValueIdFilter.Kind.NUMERIC.accept(decimal));
		assertFalse(LmdbValueIdFilter.Kind.NUMERIC.accept(string));
		assertFalse(LmdbValueIdFilter.Kind.NUMERIC.accept(iri));
		assertTrue(LmdbValueIdFilter.Kind.XSD_INTEGER.accept(genericLiteral));
		assertTrue(LmdbValueIdFilter.Kind.XSD_INTEGER.accept(integer));
		assertFalse(LmdbValueIdFilter.Kind.XSD_INTEGER.accept(decimal));
		assertFalse(LmdbValueIdFilter.Kind.XSD_INTEGER.accept(string));
		assertTrue(LmdbValueIdFilter.Kind.XSD_STRING.accept(genericLiteral));
		assertTrue(LmdbValueIdFilter.Kind.XSD_STRING.accept(string));
		assertFalse(LmdbValueIdFilter.Kind.XSD_STRING.accept(integer));
	}

	@Test
	void privateLearningProjectionPreservesOriginalOperatorTypeAndOutputMasks() {
		for (TupleExpr source : List.of(literalPattern(), new Filter(literalPattern(), truth()),
				new Join(literalPattern(), pattern("other", "v")))) {
			LeoOperatorKey original = LeoOperatorKey.from(source, "", LeoOperatorKey.ConstantMode.EXACT);
			LeoOperatorKey projected = LmdbValueIdFilter.learningKey(source, "", LeoOperatorKey.ConstantMode.EXACT);
			assertEquals(original.operatorType(), projected.operatorType());
			assertEquals(original.outputMask(), projected.outputMask());
			assertEquals(original.leftMask(), projected.leftMask());
			assertEquals(original.rightMask(), projected.rightMask());
			assertEquals(original.sharedMask(), projected.sharedMask());
		}
	}

