	@Test
	void effectiveBodyAndVariableRestrictionsShareOnlyEquivalentKeys() {
		StatementPattern body = pattern("value", "o");
		body.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:LITERAL");
		StatementPattern variable = pattern("value", "o");
		variable.getObjectVar().setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:LITERAL");
		StatementPattern overridden = pattern("value", "o");
		overridden.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:IRI");
		overridden.getSubjectVar().setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:BNODE");
		overridden.getPredicateVar().setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:RESOURCE");
		overridden.getObjectVar().setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:LITERAL");
		assertEquals(leafKey(body), leafKey(variable));
		assertEquals(leafKey(body), leafKey(overridden), "effective override order defines the semantic restriction");
		StatementPattern iri = pattern("value", "o");
		iri.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:IRI");
		assertNotEquals(leafKey(body), leafKey(iri));
	}

