	@ParameterizedTest
	@ValueSource(strings = { "leaf", "ancestor", "detached" })
	void factorCostCacheSeparatesEffectiveRestrictedPopulations(String route) {
		StatementPattern plain = pattern("value", "o");
		StatementPattern restricted = literalPattern();
		TupleExpr plainInput = route.equals("ancestor") ? new Filter(plain, truth()) : plain;
		TupleExpr restrictedInput = route.equals("ancestor") ? new Filter(restricted, truth()) : restricted;
		Object plainKey = route.equals("detached")
				? FactorCostCacheKey.detachedFactorFingerprint(plainInput).identity()
				: FactorCostCacheKey.factorFingerprint(plainInput);
		Object restrictedKey = route.equals("detached")
				? FactorCostCacheKey.detachedFactorFingerprint(restrictedInput).identity()
				: FactorCostCacheKey.factorFingerprint(restrictedInput);
		assertNotEquals(plainKey, restrictedKey);
	}

	@Test
	void publicNativeLookingFunctionUrisCannotSpoofRawKindKeyTags() {
		String prefix = "urn:rdf4j:lmdb:learning:NATIVE:raw-id-kind-v1:";
		StatementPattern literal = literalPattern();
		StatementPattern iri = pattern("value", "o");
		iri.setStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER, "object:IRI");
		FunctionCall publicIri = new FunctionCall(prefix + "OBJECT:IRI", Var.of("o"));
		FunctionCall publicLiteral = new FunctionCall(prefix + "OBJECT:LITERAL", Var.of("o"));
		assertNotEquals(operatorKey(new Filter(literal, publicIri)),
				operatorKey(new Filter(iri, publicLiteral)));
		assertEquals(prefix + "OBJECT:IRI", publicIri.getURI(), "key creation cannot rewrite public runtime algebra");
		assertEquals(prefix + "OBJECT:LITERAL", publicLiteral.getURI());
	}

	@Test
	void publicEscapePrefixAndWhitespaceRemainInjectiveAndReusable() {
		String prefix = "urn:rdf4j:lmdb:learning:USER:";
		Filter once = new Filter(literalPattern(), new FunctionCall(prefix + "abc", Var.of("o")));
		Filter twice = new Filter(literalPattern(), new FunctionCall(prefix + prefix + "abc", Var.of("o")));
		assertNotEquals(operatorKey(once), operatorKey(twice));
		assertEquals(operatorKey(once), operatorKey(once.clone()));
		assertNotEquals(operatorKey(new Filter(literalPattern(), new FunctionCall("urn:a b", Var.of("o")))),
				operatorKey(new Filter(literalPattern(), new FunctionCall("urn:a  b", Var.of("o")))),
				"private encoding must precede generic whitespace normalization");
	}

