	@ParameterizedTest
	@ValueSource(strings = { "same", "correlation", "scope", "assured", "component" })
	void retainedCandidateWithoutChildrenRequiresTheCurrentFrameAndRowScope(String variant) {
		var call = PackedCostTestSupport.binaryOperator(PlanningGraphDomain.defaultGraph(),
				new Join(pattern("value", "o"), pattern("other", "v")));
		try (var session = mappedSession(call.query())) {
			var left = estimate(2.0d);
			var right = estimate(3.0d);
			session.estimateLeaf(call.leftRelationId(), emptyContext(), left);
			session.estimateLeaf(call.rightRelationId(), emptyContext(), right);
			var candidate = estimate(6.0d);
			session.refineIntermediateJoin(call.operatorContext(2.0d, 3.0d,
					left.evidenceStateId(), right.evidenceStateId()), candidate);
			assertTrue(candidate.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_LOGICAL));
			PackedCostContext context = spy(PackedCostTestSupport.prefixContext(new int[0], 0,
					6.0d, candidate.evidenceStateId()));
			if (variant.equals("correlation")) {
				when(context.correlationMaskId()).thenReturn(1);
			} else if (variant.equals("scope")) {
				when(context.semanticScopeMaskId()).thenReturn(1);
			} else if (variant.equals("assured")) {
				when(context.assuredBindingRelationId()).thenReturn(call.leftRelationId());
			}
			var output = estimate(17.0d);
			if (variant.equals("component")) {
				output.setComponentRows(17.0d, 17.0d);
			}
			output.putPlannedStringMetric("optimizer.physicalJoinImplementation", "dependent-index");
			session.refineIntermediateJoin(context, output);
			if (variant.equals("same")) {
				assertEquals(17.0d, output.outputRows(),
						"retained evidence does not replace the selected row estimate");
				assertEquals(candidate.evidenceStateId(), output.evidenceStateId());
				assertTrue(output.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_LOGICAL));
			} else {
				assertEquals(17.0d, output.outputRows(), "a different invocation cannot restore the retained6 rows");
				assertTrue(output.runtimeFeedbackContract() == null
						|| !output.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_LOGICAL));
				assertTrue(output.runtimeFeedbackContract() == null
						|| !output.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_LIFECYCLE));
			}
		}
	}

	private static StatementPattern literalPattern() {
		QueryRoot root = new QueryRoot(new Filter(pattern("value", "o"), new IsLiteral(Var.of("o"))));
		new LmdbFilterSimplifierOptimizer(new EvaluationStatistics()).optimize(root, null, null);
		List<StatementPattern> patterns = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				patterns.add(node);
			}
		});
		assertEquals(1, patterns.size());
		StatementPattern result = patterns.getFirst();
		assertEquals("object:LITERAL", result.getStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER),
				"the real simplifier must produce the lowered semantic restriction");
		return result;
	}

	private static Object leafKey(StatementPattern source) {
		LmdbValueIdFilter.preserveEffectiveKinds(source);
		var call = PackedCostTestSupport.unaryOperator(PlanningGraphDomain.defaultGraph(), new Filter(source, truth()),
				LmdbStatementPatternSemanticsCodec.INSTANCE);
		StatementPattern packed = assertInstanceOf(StatementPattern.class,
				call.query().materializeRelation(call.inputRelationId()));
		assertEquals(source.getStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER),
				packed.getStringMetricPlanned(LmdbValueIdFilter.PLANNED_ID_FILTER));
		var output = estimate(10.0d);
		new LmdbMappedFrontierLearningSession(mock(LmdbEstimatorRuntime.class), call.query(), true)
				.applyLeaf(call.inputRelationId(), emptyContext(), output);
		return key(output);
	}

	private static Object operatorKey(TupleExpr expression) {
		LmdbValueIdFilter.preserveEffectiveKinds(expression);
		if (expression instanceof Join) {
			var call = PackedCostTestSupport.binaryOperator(PlanningGraphDomain.defaultGraph(), expression,
					LmdbStatementPatternSemanticsCodec.INSTANCE);
			var output = estimate(10.0d);
			new LmdbMappedFrontierLearningSession(mock(LmdbEstimatorRuntime.class), call.query(), true)
					.applyOperator(call.operatorRelationId(), new int[] { call.operatorRelationId() }, emptyContext(),
							output);
			return key(output);
		}
		var call = PackedCostTestSupport.unaryOperator(PlanningGraphDomain.defaultGraph(), expression,
				LmdbStatementPatternSemanticsCodec.INSTANCE);
		var output = estimate(10.0d);
		new LmdbMappedFrontierLearningSession(mock(LmdbEstimatorRuntime.class), call.query(), true)
				.applyOperator(call.operatorRelationId(), new int[] { call.operatorRelationId() }, emptyContext(),
						output);
		return key(output);
	}

	private static Object mappedJoin(StatementPattern leftPattern, boolean reversed) {
		LmdbValueIdFilter.preserveEffectiveKinds(leftPattern);
		var call = PackedCostTestSupport.binaryOperator(PlanningGraphDomain.defaultGraph(),
				new Join(leftPattern, pattern("other", "v")), LmdbStatementPatternSemanticsCodec.INSTANCE);
		try (var session = mappedSession(call.query())) {
			var left = estimate(2.0d);
			var right = estimate(3.0d);
			session.estimateLeaf(call.leftRelationId(), emptyContext(), left);
			session.estimateLeaf(call.rightRelationId(), emptyContext(), right);
			var output = estimate(6.0d);
			session.refineIntermediateJoin(reversed
					? call.operatorContext(3.0d, 2.0d, right.evidenceStateId(), left.evidenceStateId())
					: call.operatorContext(2.0d, 3.0d, left.evidenceStateId(), right.evidenceStateId()), output);
			return key(output);
		}
	}

	private static Object key(PackedCostEstimate output) {
		assertNotNull(output.runtimeFeedbackContract());
		assertTrue(output.runtimeFeedbackContract().admits(RuntimeFeedbackContract.ADMIT_LOGICAL));
		return ((LmdbRuntimeFeedbackDescriptor) output.runtimeFeedbackContract().descriptor()).logicalKey();
	}

	private static LmdbFrontierStatisticsCostSession mappedSession(PackedQueryView query) {
		return new LmdbFrontierStatisticsCostSession(mock(PackedCostSession.class), mock(LmdbPackedCostModel.class),
				mock(FrontierStatisticsView.class), query, mock(LmdbEstimatorRuntime.class), true);
	}

	private static StatementPattern pattern(String predicate, String object) {
		return new StatementPattern(Var.of("s"),
				Var.of("p", SimpleValueFactory.getInstance().createIRI("urn:test:" + predicate)), Var.of(object));
	}

	private static ValueConstant truth() {
		return new ValueConstant(SimpleValueFactory.getInstance().createLiteral(true));
	}

	private static PackedCostContext emptyContext() {
		return PackedCostTestSupport.prefixContext(new int[0], 0, 1.0d, 0);
	}

	private static PackedCostEstimate estimate(double rows) {
		var estimate = new PackedCostEstimate();
		estimate.setContextualRows(rows, rows);
		estimate.setEvidenceGuarantee(EvidenceGuarantee.SCALAR_FALLBACK);
		return estimate;
	}

	private static StatementPattern serialized(StatementPattern expression) throws Exception {
		var bytes = new ByteArrayOutputStream();
		try (var output = new ObjectOutputStream(bytes)) {
			output.writeObject(expression);
		}
		try (var input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			return (StatementPattern) input.readObject();
		}
	}
